package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string           // PIC X(2) @0 len=2
	BrAcct   string           // PIC X(4) @2 len=4
	BrType   string           // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                  // PIC X len=1 = "N"
var WsFirstFlag string = "Y"                // PIC X len=1 = "Y"
var WsPrevBranch string = "  "              // PIC X(2) len=2 = SPACES
var WsPrevAcct string = "    "              // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal = decimal.NewFromInt(0)       // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0) // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)  // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 = 0                     // PIC 99 len=2 = 0
var WsAmtEd string                          // PIC ZZ,ZZ9.99 len=9
var WsBalEd string                          // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string                          // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var curRec LedgerRec
var ledgerFile *os.File
var scanner *bufio.Scanner

func int64Pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func storeSigned(val decimal.Decimal, n int, scale int) decimal.Decimal {
	truncated := val.Truncate(int32(scale))
	scaled := truncated.Shift(int32(scale)).Truncate(0)
	isNeg := scaled.Sign() < 0
	absScaled := scaled.Abs()
	pow := int64Pow10(n + scale)
	powDec := decimal.NewFromInt(pow)
	if absScaled.Cmp(powDec) >= 0 {
		absInt := absScaled.IntPart()
		rem := absInt % pow
		newAbs := decimal.NewFromInt(rem)
		res := newAbs.Shift(int32(-scale))
		if isNeg && rem != 0 {
			res = res.Neg()
		}
		return res
	}
	return truncated
}

func formatEdited(val decimal.Decimal, pic string) string {
	hasSign := false
	if len(pic) > 0 && pic[0] == '-' {
		hasSign = true
		pic = pic[1:]
	}
	parts := strings.Split(pic, ".")
	intPic := parts[0]
	fracPic := ""
	if len(parts) > 1 {
		fracPic = parts[1]
	}
	fracDigits := len(fracPic)
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	truncVal := val.Truncate(int32(fracDigits))
	isNeg := truncVal.Sign() < 0 && !truncVal.IsZero()
	absVal := truncVal.Abs()
	scaledDec := absVal.Shift(int32(fracDigits)).Truncate(0)
	scaledInt := scaledDec.IntPart()
	powFrac := int64Pow10(fracDigits)
	intPart := scaledInt / powFrac
	fracPart := scaledInt % powFrac
	powInt := int64Pow10(intDigits)
	if intPart >= powInt {
		intPart = intPart % powInt
	}
	intDigitsStr := fmt.Sprintf("%0*d", intDigits, intPart)
	var intOut strings.Builder
	digitIdx := 0
	zeroSup := true
	for _, ch := range intPic {
		if ch == ',' {
			if zeroSup {
				intOut.WriteByte(' ')
			} else {
				intOut.WriteByte(',')
			}
		} else if ch == 'Z' {
			dch := intDigitsStr[digitIdx]
			digitIdx++
			if zeroSup && dch == '0' {
				intOut.WriteByte(' ')
			} else {
				intOut.WriteByte(dch)
				zeroSup = false
			}
		} else if ch == '9' {
			dch := intDigitsStr[digitIdx]
			digitIdx++
			intOut.WriteByte(dch)
			zeroSup = false
		}
	}
	fracStr := fmt.Sprintf("%0*d", fracDigits, fracPart)
	var result strings.Builder
	if hasSign {
		if isNeg {
			result.WriteByte('-')
		} else {
			result.WriteByte(' ')
		}
	}
	result.WriteString(intOut.String())
	if fracDigits > 0 {
		result.WriteByte('.')
		result.WriteString(fracStr)
	}
	return result.String()
}

func formatAmtEd(d decimal.Decimal) string {
	return formatEdited(d, "ZZ,ZZ9.99")
}
func formatBalEd(d decimal.Decimal) string {
	return formatEdited(d, "-Z,ZZZ,ZZ9.99")
}
func formatTotEd(d decimal.Decimal) string {
	return formatEdited(d, "-ZZZ,ZZZ,ZZ9.99")
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func isFirstRecord() bool {
	return WsFirstFlag == "Y"
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		ledgerFile = nil
		scanner = nil
	} else {
		ledgerFile = f
		scanner = bufio.NewScanner(f)
	}
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	if ledgerFile != nil {
		ledgerFile.Close()
	}
	GrandPara()
}

func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		if len(line) < 14 {
			line = line + strings.Repeat(" ", 14-len(line))
		} else if len(line) > 14 {
			line = line[:14]
		}
		curRec.BrBranch = line[0:2]
		curRec.BrAcct = line[2:6]
		curRec.BrType = line[6:7]
		brAmtStr := line[7:14]
		cleaned := strings.ReplaceAll(brAmtStr, " ", "")
		if cleaned == "" {
			curRec.BrAmt = decimal.NewFromInt(0)
		} else {
			v, err := strconv.ParseInt(cleaned, 10, 64)
			if err != nil {
				v = 0
			}
			curRec.BrAmt = decimal.New(v, -2)
		}
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, "read error:", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = formatAmtEd(curRec.BrAmt)
	switch curRec.BrType {
	case "D":
		WsBal = storeSigned(WsBal.Add(curRec.BrAmt), 7, 2)
		line := curRec.BrAcct + " D " + WsAmtEd
		fmt.Printf("%s\n", line)
	case "C":
		WsBal = storeSigned(WsBal.Sub(curRec.BrAmt), 7, 2)
		line := curRec.BrAcct + " C " + WsAmtEd
		fmt.Printf("%s\n", line)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		line := curRec.BrAcct + " ? SKIPPED"
		fmt.Printf("%s\n", line)
	}
}

func AcctBreakPara() {
	WsBalEd = formatBalEd(WsBal)
	line := "  ACCOUNT " + WsPrevAcct + " BALANCE:" + WsBalEd
	fmt.Printf("%s\n", line)
	WsBranchTot = storeSigned(WsBranchTot.Add(WsBal), 9, 2)
	WsBal = decimal.NewFromInt(0)
}

func BranchBreakPara() {
	WsTotEd = formatTotEd(WsBranchTot)
	line := " BRANCH " + WsPrevBranch + " TOTAL:" + WsTotEd
	fmt.Printf("%s\n", line)
	WsGrandTot = storeSigned(WsGrandTot.Add(WsBranchTot), 9, 2)
	WsBranchTot = decimal.NewFromInt(0)
}

func GrandPara() {
	WsTotEd = formatTotEd(WsGrandTot)
	line := "GRAND TOTAL:" + WsTotEd
	fmt.Printf("%s\n", line)
	skippedStr := fmt.Sprintf("%02d", WsSkipped)
	line2 := "SKIPPED: " + skippedStr
	fmt.Printf("%s\n", line2)
}

func main() {
	MainPara()
}
